const std=@import("std");
pub fn exposure(height:f64,depth:f64)?f64{@setFloatMode(.strict);if(!std.math.isFinite(height) or !std.math.isFinite(depth) or height<0 or depth<0)return null;if(height==0)return if(depth==0)1 else 0;return if(depth>=height)0 else (height-depth)/height;}
pub fn meanReserve(w:f64,loss:f64,cap:f64)?f64{@setFloatMode(.strict);if(!std.math.isFinite(w) or !std.math.isFinite(loss) or !std.math.isFinite(cap) or w<0 or loss<0 or cap<0 or w>cap)return null;if(cap==0)return 0;if(loss==0)return w/cap;return if(loss<=w)(w-loss*0.5)/cap else (w/cap)*(w/loss)*0.5;}
test "height and tiny-film conventions and bounded mean signal"{try std.testing.expectEqual(@as(f64,1),exposure(0,0).?);try std.testing.expectEqual(@as(f64,0),exposure(0,1e-300).?);try std.testing.expectEqual(@as(f64,0.5),exposure(0.5,0.25).?);try std.testing.expectEqual(@as(f64,0),exposure(0.01,0.1).?);try std.testing.expect(exposure(-1,0)==null);try std.testing.expectEqual(@as(f64,0),meanReserve(0,1,1).?);try std.testing.expectEqual(@as(f64,1),meanReserve(1,0,1).?);try std.testing.expectEqual(@as(f64,0.5),meanReserve(1,1,1).?);try std.testing.expectEqual(@as(f64,0.25),meanReserve(1,2,1).?);try std.testing.expect(meanReserve(2,1,1)==null);try std.testing.expect(meanReserve(1,std.math.nan(f64),1)==null);}
